package com.hmdp.upgrade;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.time.Instant;
import java.util.*;
import javax.imageio.ImageIO;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.core.io.ByteArrayResource;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.util.LinkedMultiValueMap;
import static org.junit.jupiter.api.Assertions.*;

/** Real MySQL migration + HTTP auth/CSRF/role/media boundary, enabled only in the isolated verify database. */
@EnabledIfEnvironmentVariable(named="ASSISTANT_INTEGRATION",matches="true")
@org.springframework.test.annotation.DirtiesContext
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"upgrade.local-life.enabled=true","upgrade.local-life.demo-data=true","upgrade.core32.enabled=false","upgrade.assistant.mode=stub","upgrade.jobs=false"})
class LocalLifeIntegrationTest {
    @Autowired TestRestTemplate http;@Autowired JdbcTemplate db;@Autowired ObjectMapper json;
    record Client(String cookie,String csrf,String id){}
    ResponseEntity<Map> call(HttpMethod method,String path,Client c,Object body){var h=new HttpHeaders();h.setContentType(MediaType.APPLICATION_JSON);if(c!=null){h.set("Cookie",c.cookie);h.set("X-CSRF-Token",c.csrf);h.set("X-Account-ID",c.id);}return http.exchange("/v2"+path,method,new HttpEntity<>(body,h),Map.class);}
    Client user(boolean operator){String username="local_"+UUID.randomUUID().toString().replace("-","").substring(0,12);var r=call(HttpMethod.POST,"/auth/register",null,Map.of("username",username,"password","integration-test-only-password","displayName","生活验收用户"));assertEquals(201,r.getStatusCode().value(),r.toString());var who=(Map)r.getBody().get("user");var c=new Client(r.getHeaders().getFirst("Set-Cookie").split(";")[0],r.getBody().get("csrfToken").toString(),who.get("id").toString());if(operator)db.update("INSERT INTO ux_local_profile(user_id,role,updated_at) VALUES(?,'OPERATOR',CURRENT_TIMESTAMP)",c.id);return c;}
    Map<String,Object> shopPayload(){return new LinkedHashMap<>(Map.ofEntries(Map.entry("name","验收专用咖啡馆"),Map.entry("description","这是专门在独立验收数据库创建的商铺，不进入正式演示统计。"),Map.entry("category","咖啡茶饮"),Map.entry("campus","主校区"),Map.entry("area","大学路"),Map.entry("address","虚构验收地址"),Map.entry("status","PUBLISHED"),Map.entry("coverPath","/local-assets/shop-2.svg"),Map.entry("photos",List.of("/local-assets/shop-2.svg","/local-assets/interior-2.svg","/local-assets/menu-2.svg")),Map.entry("tags",List.of("安静")),Map.entry("hours",List.of(Map.of("day",1,"start","09:00","end","22:00"))),Map.entry("avgPriceCents",3000)));}
    @Test void realMigrationRolesStorefrontVersionAndInvalidationAreUsable(){assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM flyway_schema_history WHERE version='18' AND success=TRUE",Integer.class));var op=user(true);var regular=user(false);assertEquals(403,call(HttpMethod.GET,"/ops/overview",regular,null).getStatusCode().value());var invalid=new Client(op.cookie,"bad",op.id);assertEquals(403,call(HttpMethod.POST,"/ops/shops",invalid,shopPayload()).getStatusCode().value());var created=call(HttpMethod.POST,"/ops/shops",op,shopPayload());assertEquals(200,created.getStatusCode().value(),created.toString());String id=created.getBody().get("id").toString();var changed=shopPayload();changed.put("name","修改后的验收咖啡馆");changed.put("version",1);assertEquals(200,call(HttpMethod.PUT,"/ops/shops/"+id,op,changed).getStatusCode().value());assertEquals(409,call(HttpMethod.PUT,"/ops/shops/"+id,op,changed).getStatusCode().value());assertEquals("修改后的验收咖啡馆",db.queryForObject("SELECT name FROM ux_shop WHERE id=?",String.class,id));}
    @Test void realCouponFlowIsIdempotentAndNotVisibleAcrossAccounts(){var op=user(true);var alice=user(false);var bob=user(false);String shop=call(HttpMethod.POST,"/ops/shops",op,shopPayload()).getBody().get("id").toString();var b=Map.ofEntries(Map.entry("shopId",shop),Map.entry("title","验收满100减20"),Map.entry("minimumCents",10000),Map.entry("discountCents",2000),Map.entry("capacity",2),Map.entry("claimFrom",Instant.now().minusSeconds(60).toString()),Map.entry("claimUntil",Instant.now().plusSeconds(3600).toString()),Map.entry("validFrom",Instant.now().minusSeconds(60).toString()),Map.entry("validUntil",Instant.now().plusSeconds(7200).toString()),Map.entry("terms","仅限验收模拟核销，免费领取且不能叠加。"),Map.entry("state","PUBLISHED"));var template=call(HttpMethod.POST,"/ops/coupon-templates",op,b);assertEquals(200,template.getStatusCode().value(),template.toString());String tid=template.getBody().get("id").toString();var first=call(HttpMethod.POST,"/coupons/"+tid+"/claim",alice,null);assertEquals(200,first.getStatusCode().value());String cid=first.getBody().get("id").toString();assertEquals(cid,call(HttpMethod.POST,"/coupons/"+tid+"/claim",alice,null).getBody().get("id"));assertEquals(404,call(HttpMethod.GET,"/account/coupons/"+cid,bob,null).getStatusCode().value());var detail=call(HttpMethod.GET,"/account/coupons/"+cid,alice,null);var redeem=Map.of("shopId",shop,"code",detail.getBody().get("redeemCode"),"amountCents",12000,"requestKey",UUID.randomUUID().toString());var result=call(HttpMethod.POST,"/ops/coupon-redemptions",op,redeem);assertEquals(200,result.getStatusCode().value(),result.toString());assertEquals(result.getBody(),call(HttpMethod.POST,"/ops/coupon-redemptions",op,redeem).getBody());assertEquals(409,call(HttpMethod.POST,"/ops/coupons/"+cid+"/void",op,Map.of("requestKey",UUID.randomUUID().toString(),"reason","已核销的券不应允许作废")).getStatusCode().value());assertEquals(1,db.queryForObject("SELECT remaining FROM ux_coupon_template WHERE id=?",Integer.class,tid));}
    @Test void multipartUploadRespectsCsrfOwnershipAndModeration()throws Exception{var alice=user(false);var bob=user(false);var op=user(true);var image=new ByteArrayOutputStream();ImageIO.write(new BufferedImage(30,20,BufferedImage.TYPE_INT_RGB),"png",image);var body=new LinkedMultiValueMap<String,Object>();body.add("purpose","REVIEW");body.add("file",new ByteArrayResource(image.toByteArray()){@Override public String getFilename(){return "review.png";}});var headers=new HttpHeaders();headers.setContentType(MediaType.MULTIPART_FORM_DATA);headers.set("Cookie",alice.cookie);headers.set("X-CSRF-Token",alice.csrf);headers.set("X-Account-ID",alice.id);var upload=http.postForEntity("/v2/media",new HttpEntity<>(body,headers),Map.class);assertEquals(200,upload.getStatusCode().value(),upload.toString());String id=upload.getBody().get("id").toString();assertEquals(404,http.getForEntity("/v2/media/"+id,byte[].class).getStatusCode().value());var review=call(HttpMethod.POST,"/local/shops/32001/reviews",alice,Map.of("rating",5,"body","这是一条带图片的真实 HTTP 验收评价，用于检查媒体访问权限。","mediaIds",List.of(id)));assertEquals(200,review.getStatusCode().value(),review.toString());assertEquals(200,http.getForEntity("/v2/media/"+id,byte[].class).getStatusCode().value());String rid=review.getBody().get("id").toString();assertEquals(200,call(HttpMethod.PATCH,"/ops/reviews/"+rid+"/state",op,Map.of("state","HIDDEN","version",1,"reason","验收暂时隐藏评价和图片")).getStatusCode().value());assertEquals(404,http.getForEntity("/v2/media/"+id,byte[].class).getStatusCode().value());assertEquals(404,call(HttpMethod.GET,"/reviews/"+rid,bob,null).getStatusCode().value());assertEquals(200,call(HttpMethod.GET,"/reviews/"+rid,alice,null).getStatusCode().value());}
}
